import React, { useEffect, useRef } from 'react';

export default function CountyMap() {
  const mapRef = useRef(null);

  useEffect(() => {
    if (!window.L) return; // Leaflet not loaded yet

    const L = window.L;
    if (mapRef.current) return;

    mapRef.current = L.map('map').setView([-1.0, 36.8], 6);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(mapRef.current);

    fetch('http://127.0.0.1:8000/api/geojson/kenya_counties/')
      .then((res) => res.json())
      .then((data) => {
        L.geoJSON(data, {
          style: () => ({ color: '#2c7bb6', weight: 2, fillOpacity: 0.3 }),
          onEachFeature: (feature, layer) => {
            const name = feature.properties && feature.properties.name;
            layer.bindPopup(name || 'County');
          }
        }).addTo(mapRef.current);
      })
      .catch((err) => console.error('GeoJSON load failed', err));
  }, []);

  return (
    <div style={{ height: '480px', width: '100%', marginBottom: '1rem' }} id="map"></div>
  );
}
